    brief_exchange: {
      id: 'brief_exchange',
      label: 'Say something',
      location: 'street',
      available: () => {
        return ctx.state.neighborTier() === 'known'
          && ctx.state.get('neighbor_archetype') !== null;
      },
      execute: () => {
        ctx.state.advanceTime(3);
        ctx.state.set('neighbor_encounters', ctx.state.get('neighbor_encounters') + 1);
        ctx.state.adjustNT('serotonin', 2); // Approximation debt (reputation): familiar exchange; serotonin direction from social connection literature (Holt-Lunstad et al. 2015 PMID 25910392); magnitude chosen
        ctx.state.adjustSocial(5);
        ctx.state.adjustConnectionDepth(1); // Approximation debt (social depth): +1 chosen; brief block-level exchange weaker than friend contact; no published per-interaction magnitude data

        const name = ctx.state.get('neighbor_name');
        const archetype = ctx.state.get('neighbor_archetype');
        const nPronounSet = ctx.state.get('neighbor_pronoun_set');
        const pSubj = nPronounSet ? (nPronounSet.subject.charAt(0).toUpperCase() + nPronounSet.subject.slice(1)) : 'They';

        // 2 RNG calls
        const opening = ctx.timeline.cosmeticWeightedPick([
          { weight: 1, value: `${name}.` },
          { weight: 0.8, value: `You say ${name}'s name.` },
          { weight: 0.6, value: `"Hey."` },
        ]);

        const exchange = ctx.timeline.cosmeticWeightedPick([
          { weight: 1, value: archetype === 'dog_walker'
            ? `${pSubj} stop for a moment with the dog. Ask how you've been. You say fine. ${pSubj} say good. The dog looks at something down the street.`
            : archetype === 'always_smoking'
            ? `${pSubj} take a drag before answering. Something about the weather, or the building. You say something back. It doesn't need to go anywhere.`
            : archetype === 'front_stoop'
            ? `A few words from the step. ${pSubj} ask something simple. You answer. ${pSubj} nod. That's the shape of it — not a conversation, just contact.`
            : archetype === 'early_commuter'
            ? `A few words going the same direction. Catching up to the bus, the train, whatever. Brief. Real enough.`
            : archetype === 'night_shift'
            ? `${pSubj} look a little tired. So do you, probably. A few words. Something about the schedule, the hours. ${pSubj} knows.`
            : archetype === 'music_person'
            ? `${pSubj} pull one earbud out. Not both — just one. Ask how you're doing. You tell ${nPronounSet ? nPronounSet.object : 'them'}. ${pSubj} smiles, puts the earbud back.`
            : `${pSubj} say something. You say something back. The specific warmth of someone who knows you well enough to ask without it being anything.`
          },
        ]);

        // Illness modifier — running into the neighbor while sick
        let illNeighSuffix = '';
        {
          const illN = ctx.state.illnessTier();
          if (illN === 'very_sick') {
            illNeighSuffix = ` You said you were fine. You don't know what you looked like when you said it.`;
          } else if (illN === 'sick') {
            illNeighSuffix = ` You said you were fine.`;
          }
        }

        // Cramps modifier — brief contact while cramping; deterministic
        let crampsNeighSuffix = '';
        if (ctx.body.hasUterus() && ctx.state.get('cramps_active') && !ctx.state.isCrampRelieved()) {
          const crampSev = ctx.state.get('cramp_severity') || 0;
          if (crampSev > 0.6) {
            crampsNeighSuffix = ' The cramps were there the whole time. You held the conversation anyway.';
          }
        }

        ctx.state.adjustSentiment('neighbor_familiarity', 'comfort', -0.001); // Approximation debt (comfort habituation): neighbor familiarity comfort habituates; rate chosen
        return `${opening} ${exchange}` + illNeighSuffix + crampsNeighSuffix;
      },
    },

