    browse_store: {
      id: 'browse_store',
      label: 'Look around',
      location: 'corner_store',
      available: () => !ctx.state.get('browsing_store'),
      execute: () => {
        ctx.state.advanceTime(5);

        const money = ctx.state.moneyTier();
        const hunger = ctx.state.hungerTier();

        let text;
        if (money === 'overdrawn') {
          text = 'You walk the aisles. Everything has a number and you\'re already below zero. You walk through anyway.';
        } else if (money === 'broke') {
          text = 'You walk the aisles. Everything has a number attached and the numbers all say no.';
        } else if (hunger === 'starving' && (money === 'scraping' || money === 'tight')) {
          text = 'You look at things you want and things you can afford and the overlap is very small.';
        } else if (money === 'scraping') {
          text = 'You look at the prices. You know most of them already. They haven\'t gotten better.';
        } else {
          text = 'You walk through. The fluorescent aisles. Same stuff as always. You don\'t need anything specific, but you look.';
        }

        // NT deterministic modifiers (no RNG — replay-safe)
        const dopa = ctx.state.get('dopamine');
        const aden = ctx.state.get('adenosine');
        if (money !== 'broke' && money !== 'overdrawn' && dopa < 35) {
          text += ' Nothing in here catches you. The things are just things.';
        } else if (aden > 65 && ctx.state.adenosineBlock() > 0.4) {
          text += ' You move through the aisles without fully seeing them.';
        }

        // ADHD layer-3 — went in for something; object permanence working against you; deterministic, no RNG.
        if (ctx.state.get('adhd') ?? false) {
          text += ' You came in for something specific. You\'re not sure what anymore.';
        }
        // Autism layer-3 — store layout is known; predictable aisles are easy to navigate; deterministic, no RNG.
        if (ctx.state.get('autism') ?? false) {
          text += ' You know this layout. Same place as always.';
        }

        // Ethical stance layer-3 — deterministic, no RNG. Vegan/vegetarian navigate past meat sections automatically.
        const browseStance = ctx.state.get('ethical_stance');
        if (browseStance === 'vegan' || browseStance === 'vegetarian') {
          text += ' You move past the meat section without stopping.';
        }

        return text;
      },
    },

