    buy_medicine: {
      id: 'buy_medicine',
      label: 'Get something for it',
      location: 'corner_store',
      available: () => ctx.state.illnessTier() !== 'healthy' && ctx.state.canAfford(cornerStorePrice(9)) && !ctx.events.any('took_medicine', ctx.state.get('wake_period_start')),
      execute: () => {
        const cost = ctx.timeline.randomFloat(cornerStorePrice(9), cornerStorePrice(13));
        const roundedCost = Math.round(cost * 100) / 100;
        if (!ctx.state.spendMoney(roundedCost)) return 'Not enough. You put it back.';
        ctx.events.record('took_medicine');
        ctx.state.advanceTime(ctx.timeline.randomInt(5, 8));
        ctx.state.glanceMoney();

        const illTier = ctx.state.illnessTier();
        const aden = ctx.state.get('adenosine');

        // Appearance — deterministic modifier (layer 3, no RNG).
        // When very sick, illness already commands the body's full attention — appearance signal
        // is smaller. At notable/severe appearance, being sick AND visibly rough compounds.
        // Approximation debt (appearance): NE +3/+5, GABA -2; direction: social phobia shows elevated plasma NE (Stein et al. 1992 PMID 1558465); self-focused attention model (Rapee & Heimberg 1997 PMID 9256517); GABAergic deficit in anxiety disorders (Möhler 2012 PMID 21889518); no individual-level magnitude data.
        const appearance = ctx.state.appearanceAwareness();
        let appearanceSuffix = '';
        if (appearance === 'severe' && illTier !== 'very_sick') {
          ctx.state.adjustNT('norepinephrine', 5);  // Approximation debt (appearance):
          ctx.state.adjustNT('gaba', -2);            // Approximation debt (appearance):
          ctx.state.adjustNT('serotonin', -2);       // Approximation debt (appearance):
          appearanceSuffix = ' You\'re aware of yourself at the counter. The particular awareness of being seen when you\'re not at your best.';
        } else if (appearance === 'notable' && illTier !== 'very_sick') {
          ctx.state.adjustNT('norepinephrine', 3);  // Approximation debt (appearance):
          ctx.state.adjustNT('serotonin', -1);       // Approximation debt (appearance):
        }

        // Autism camouflaging suffix — deterministic layer-3, no RNG.
        // Brief stranger transaction: scripts calibrated by social_energy.
        const autismSuffix = getAutismCashierSuffix();

        // Cramps modifier — being sick and also cramping; or cramping severe enough to prompt this; deterministic
        let crampsMedicineSuffix = '';
        if (ctx.body.hasUterus() && ctx.state.get('cramps_active') && !ctx.state.isCrampRelieved()) {
          const crampSev = ctx.state.get('cramp_severity') || 0;
          if (crampSev > 0.3) {
            crampsMedicineSuffix = ' The cramps didn\'t help.';
          }
        }

        if (illTier === 'very_sick') {
          return ctx.timeline.cosmeticWeightedPick([
            { weight: 1, value: 'You find what you need and bring it to the register. The cashier doesn\'t comment. You get home and take it. It won\'t fix anything, but it will make it possible to exist in your body for a while.' },
            { weight: 1, value: 'Cold medicine. You take it in the store parking lot because you can\'t wait. The chemical taste is almost comforting — something doing something.' },
          ]) + crampsMedicineSuffix + autismSuffix;
        }
        if (illTier === 'sick') {
          return ctx.timeline.cosmeticWeightedPick([
            { weight: 1, value: 'DayQuil or NyQuil or whatever the generic version is. You take the recommended dose, which feels insufficient. You take it anyway.' },
            { weight: 1, value: 'You find the right aisle, pick something up, pay. You already feel slightly better just from the act of doing something about it.' },
            // High adenosine — the shopping itself was an effort
            { weight: ctx.state.lerp01(aden, 50, 80) * ctx.state.adenosineBlock(), value: 'The walk here took most of what you had. You get the medicine, get out. That\'s enough for now.' },
          ]) + crampsMedicineSuffix + appearanceSuffix + autismSuffix;
        }
        return ctx.timeline.cosmeticWeightedPick([
          { weight: 1, value: 'Something to head it off before it gets worse. Or just help. Either way.' },
          { weight: 1, value: 'You grab cold medicine, the generic kind. Probably the same thing in the box. You pay and go.' },
        ]) + crampsMedicineSuffix + appearanceSuffix + autismSuffix;
      },
    },

