        ctx.state.glanceMoney();

        // Dental — hot coffee is a trigger
        ctx.state.dentalSpike(25); // Calibrated: within +20–33 range for pulpitis thermal trigger (PMC3819160, Allison 2020)

        const mood = ctx.state.moodTone();
